// Registers one composition per video folder listed in videos/liste.ts (generated by scripts/liste.mjs).
// Each composition = the video's 3D scene + French word-by-word subtitles from its words.json.
import React from "react";
import { Composition } from "remotion";
import { VIDEOS } from "./videos/liste";
import { Short } from "./commun/Short";

export const Root: React.FC = () => (
  <>
    {VIDEOS.map((v) => (
      <React.Fragment key={v.id}>
        <Composition id={v.id} component={Short} defaultProps={{ id: v.id }} durationInFrames={v.frames} fps={30} width={1080} height={1920} />
        <Composition id={v.id + "-720"} component={Short} defaultProps={{ id: v.id }} durationInFrames={v.frames} fps={30} width={720} height={1280} />
      </React.Fragment>
    ))}
  </>
);
